41.     }
42. }
43. 
44. /// Errors returned by the GitHub release client.
45. #[derive(Debug, Error)]
46. pub enum ReleaseClientError {
47.     /// The HTTP request or response decoding failed.
48.     #[error(transparent)]
49.     Http(#[from] reqwest::Error),
50. }
51. 
52. /// Reqwest-backed client for GitHub release metadata.
53. #[derive(Debug, Clone)]
54. pub struct ReqwestReleaseClient {
55.     client: reqwest::Client,
56.     latest_release_url: &'static str,
57. }
58. 
