1. //! `derrick upgrade` — reserved binary self-update command.
2. 
3. use crate::commands::UpgradeArgs;
4. use crate::exit_code::CliExitCode;
5. 
6. pub(crate) async fn execute(_args: UpgradeArgs) -> Result<CliExitCode, crate::CliError> {
7.     use std::io::Write as _;
8. 
9.     std::io::stdout()
10.         .lock()
11.         .write_all(
12.             b"derrick upgrade is not yet available; future releases will use GitHub release assets\n",
13.         )
14.         .map_err(|source| crate::CliError::Io {
15.             path: std::path::PathBuf::from("<stdout>"),
16.             source,
17.         })?;
18.     Ok(CliExitCode::Success)
19. }
20.

