1. //! Minimal derrick command-line interface for T008.
2. 
3. #![allow(clippy::print_stdout)]
4. #![allow(clippy::print_stderr)]
5. 
6. use std::ffi::OsString;
7. use std::path::{Path, PathBuf};
8. use std::process::ExitCode;
9. 
10. use clap::{CommandFactory, Parser};
11. use commands::{Cli, Command};
12. use thiserror::Error;
13. 
14. mod commands;
15. mod exit_code;
16. mod output;
17. mod telemetry;
18. 
19. pub mod upgrade;
20. 
21. /// Runs the CLI with an argument iterator and returns the process exit code.
22. pub async fn run<I, T>(args: I) -> ExitCode
23. where
24.     I: IntoIterator<Item = T>,
25.     T: Into<OsString> + Clone,
26. {
27.     let cli = match Cli::try_parse_from(args) {
28.         Ok(cli) => cli,
29.         Err(error) => {
30.             let code = error.exit_code();
31.             if let Err(print_error) = error.print() {
32.                 eprintln!("failed to print clap error: {print_error}");
33.             }
34.             return exit_code::from_i32(code);
35.         }
36.     };
37. 
38.     match dispatch(cli).await {
39.         Ok(code) => code.into(),
40.         Err(error) => {
41.             eprintln!("{error}");
42.             ExitCode::from(1)
43.         }
44.     }
45. }
46. 
47. async fn dispatch(cli: Cli) -> Result<exit_code::CliExitCode, CliError> {
48.     match cli.command {
49.         Command::Add(args) => commands::add::execute(args).await,
50.         Command::Init(args) => commands::init::execute(args).await,
51.         Command::Status(args) => commands::status::execute(args).await,
52.         Command::Doctor(args) => commands::doctor::execute(args).await,
53.         Command::Run(args) => commands::run::execute(args).await,
54.         Command::Completions(args) => {
55.             commands::completions::execute(args, &mut Cli::command());
56.             Ok(exit_code::CliExitCode::Success)
57.         }
58.         Command::Ticket(args) => commands::ticket::execute(args).await,
59.         Command::Foreman(args) => commands::foreman::execute(args).await,
60.         Command::Stack(args) => commands::stack::execute(args).await,
61.         Command::Observe(args) => commands::observe::execute(args).await,
62.         Command::Uninstall(args) => commands::uninstall::execute(args).await,
63.         Command::Upgrade(args) => commands::upgrade::execute(args).await,
64.         Command::Scrub(args) => commands::scrub::run(args)
65.             .await
66.             .map(|()| exit_code::CliExitCode::Success)
67.             .map_err(|error| message(error.to_string())),
68.         Command::Caveman(args) => commands::caveman::run(args)
69.             .await
70.             .map(|()| exit_code::CliExitCode::Success)
71.             .map_err(|error| message(error.to_string())),
72.         Command::Gain(args) => commands::gain::run(args)
73.             .await
74.             .map(|()| exit_code::CliExitCode::Success)
75.             .map_err(|error| message(error.to_string())),
76.         Command::Switch(args) => commands::switch::execute(args).await,
77.     }
78. }
79. 
80. #[derive(Debug, Error)]
81. enum CliError {
82.     #[error("{0}")]
83.     Message(String),
84.     #[error("IO error at {path}: {source}")]
85.     Io {
86.         path: PathBuf,
87.         source: std::io::Error,
88.     },
89.     #[error("{0}")]
90.     Config(#[from] derrick_config::ConfigError),
91.     #[error("{0}")]
92.     Substrate(#[from] derrick_substrate::SubstrateError),
93.     #[error("{0}")]
94.     Adopt(#[from] derrick_adopt::AdoptError),
95.     #[error("{0}")]
96.     Json(#[from] serde_json::Error),
97. }
98. 
99. fn message(text: impl Into<String>) -> CliError {
100.     CliError::Message(text.into())
101. }
102. 
103. fn find_repo_root(start: &Path) -> Result<PathBuf, CliError> {
104.     for candidate in start.ancestors() {
105.         if candidate.join(".git").exists() {
106.             return Ok(candidate.to_path_buf());
107.         }
108.     }
109. 
110.     Err(message("derrick init must be run inside a git repo"))
111. }
112. 
113. fn current_repo_root() -> Result<PathBuf, CliError> {
114.     let cwd = std::env::current_dir().map_err(|source| CliError::Io {
115.         path: PathBuf::from("."),
116.         source,
117.     })?;
118.     find_repo_root(&cwd)
119. }
120. 
121. fn read_config(repo_root: &Path) -> Result<derrick_config::Config, CliError> {
122.     derrick_config::Config::load_from_path(&repo_root.join("derrick.yaml")).map_err(Into::into)
123. }
124. 
125. fn native_paths(
126.     repo_root: &Path,
127.     config: &derrick_config::Config,
128. ) -> derrick_substrate_native::NativeConfig {
129.     derrick_substrate_native::NativeConfig {
130.         db_path: repo_root.join(config.state().dir()).join("derrick.db"),
131.         worktree_root: repo_root.join(config.state().worktree_root()),
132.     }
133. }
134. 
135. fn write_file(path: &Path, contents: &str) -> Result<(), CliError> {
136.     std::fs::write(path, contents).map_err(|source| CliError::Io {
137.         path: path.to_path_buf(),
138.         source,
139.     })
140. }
141. 
142. fn create_dir_all(path: &Path) -> Result<(), CliError> {
143.     std::fs::create_dir_all(path).map_err(|source| CliError::Io {
144.         path: path.to_path_buf(),
145.         source,
146.     })
147. }
