1. //! CLI integration tests for the T012 `ticket` and `foreman` subcommands.
2. 
3. #![cfg(unix)]
4. 
5. use std::fs;
6. use std::path::{Path, PathBuf};
7. use std::time::{Duration, Instant};
8. 
9. use assert_cmd::Command;
10. use derrick_config::{Config, Site};
11. use derrick_substrate::{
12.     BatchName, BlockReason, LinkKind, NewTicket, Substrate, TicketId, TicketState,
13. };
14. use derrick_substrate_native::{NativeConfig, NativeSubstrate};
15. use tempfile::TempDir;
16. 
17. type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;
18. 
19. fn derrick() -> TestResult<Command> {
20.     Ok(Command::cargo_bin("derrick")?)
21. }
22. 
23. fn make_repo(mode: &str) -> TestResult<TempDir> {
24.     let dir = tempfile::tempdir()?;
25.     fs::create_dir(dir.path().join(".git"))?;
26.     derrick()?
27.         .current_dir(dir.path())
28.         .env("DERRICK_SKIP_PREREQS", "1")
29.         .args([
30.             "init",
31.             "--greenfield",
32.             "--site",
33.             "test",
34.             "--prefix",
35.             "tst",
36.             "--mode",
37.             mode,
38.             "--yes",
39.         ])
40.         .assert()
41.         .success();
42.     Ok(dir)
43. }
44. 
45. fn config_for(dir: &Path) -> TestResult<Config> {
46.     Ok(Config::load_from_path(&dir.join("derrick.yaml"))?)
47. }
48. 
49. fn native_paths(dir: &Path, config: &Config) -> NativeConfig {
50.     NativeConfig {
51.         db_path: dir.join(config.state().dir()).join("derrick.db"),
52.         worktree_root: dir.join(config.state().worktree_root()),
53.     }
54. }
55. 
56. async fn open_substrate(dir: &Path) -> TestResult<NativeSubstrate> {
57.     let config = config_for(dir)?;
58.     let native_config = native_paths(dir, &config);
59.     let site: Site = config.site().clone();
60.     Ok(NativeSubstrate::open(native_config, site).await?)
61. }
62. 
63. async fn seed_ticket(substrate: &NativeSubstrate, id: &str) -> TestResult<TicketId> {
64.     let ticket_id = TicketId::new(id)?;
65.     let batch_name = BatchName::new("batch-1")?;
66.     if substrate.get_batch(&batch_name).await?.is_none() {
67.         substrate.create_batch(batch_name.clone()).await?;
68.     }
69.     substrate
70.         .create_ticket(NewTicket::new(
71.             ticket_id.clone(),
72.             Some(batch_name),
73.             None,
74.             format!("title for {id}"),
75.             "",
76.             Vec::new(),
77.         )?)
78.         .await?;
79.     Ok(ticket_id)
80. }
81. 
82. // --- Tests ---------------------------------------------------------------
83. 
84. #[tokio::test(flavor = "multi_thread")]
85. async fn cli_ticket_done_refuses_in_crew_mode() -> TestResult {
86.     let dir = make_repo("crew")?;
87.     let substrate = open_substrate(dir.path()).await?;
88.     seed_ticket(&substrate, "tst-1").await?;
89.     drop(substrate); // release SQLite handle before invoking the CLI
90. 
91.     let output = derrick()?
92.         .current_dir(dir.path())
93.         .args(["ticket", "done", "tst-1", "--note", "n"])
94.         .assert()
95.         .failure()
96.         .get_output()
97.         .clone();
98.     assert_eq!(output.status.code(), Some(2));
99.     let stderr = String::from_utf8_lossy(&output.stderr);
100.     assert!(
101.         stderr.contains("\u{a7}8.6") || stderr.contains("D31"),
102.         "expected D31 pointer in stderr; got: {stderr}"
103.     );
104.     Ok(())
105. }
106. 
107. #[tokio::test(flavor = "multi_thread")]
108. async fn cli_ticket_done_succeeds_in_solo_mode() -> TestResult {
109.     let dir = make_repo("solo")?;
110.     let substrate = open_substrate(dir.path()).await?;
111.     let ticket_id = seed_ticket(&substrate, "tst-1").await?;
112.     drop(substrate);
113. 
114.     derrick()?
115.         .current_dir(dir.path())
116.         .args(["ticket", "done", "tst-1", "--note", "manual"])
117.         .assert()
118.         .success();
119. 
120.     let substrate = open_substrate(dir.path()).await?;

