        );
    }

    #[test]
    fn user_agent_uses_package_version() {
        assert_eq!(
            user_agent(),
            format!("derrick/{}", env!("CARGO_PKG_VERSION"))
        );
    }

    #[test]
    fn release_deserializes_from_github_shape() {
        let release: GithubRelease = serde_json::from_str(
            r#"{
